INSERT INTO plans (carrier_id,name,price_cents,data_allowance,talk,texts,validity_days,description,popular,active,verify_pricing,sort_order) VALUES (18,'Essentials monthly',1000,'3GB high-speed','Unlimited','Unlimited',0,'Published monthly account rate; confirm eligible network and fulfilment product. Current official comparison lists $10 Essentials, $20 Plus and $30 Unlimited Premium. Network, account and plan generation matter. Exclude first-month, referral and annual discounts from refill pricing. Do not treat a monthly price as proof of a generic PIN product.',0,1,1,10);
