INSERT INTO carriers (id,name,slug,color,description,number_hint,source_url,active,sort_order) VALUES (19,'Tello','tello','#0A7B8C','Explore prepaid options for your existing Tello number. Confirm your plan is eligible before ordering.','Enter your existing 10-digit US prepaid mobile number.','https://tello.com/help_center/new-to-tello/how-does-pay-as-you-go-work',1,190);
INSERT INTO plans (carrier_id,name,price_cents,data_allowance,talk,texts,validity_days,description,popular,active,verify_pricing,sort_order) VALUES (19,'$20 PAYG website minimum refill',2000,'','','',0,'Metered credit for the customer''s account; not a monthly service bundle. Official website PAYG initial/manual refill minimum is $20. This is separate from monthly plans and is not a transferable refill-card SKU. Credit stays valid with an active plan but expires after three months without one; no universal validity is assigned. Third-party fulfilment remains unverified.',0,1,1,10);
