INSERT INTO plans (carrier_id,name,price_cents,data_allowance,talk,texts,validity_days,description,popular,active,verify_pricing,sort_order) VALUES (21,'1GB/month 12-month upfront',6000,'1GB high-speed per month','Unlimited','Unlimited',0,'Official annual-price reference; full $60 upfront, with account eligibility unverified. The official annual page lists $60 paid upfront for 12 months with 1GB per month. This is not a $5 standalone monthly refill or generic $60 account-credit card. The main dynamic plan grid did not expose pricing in this research; confirm the annual offer, existing-customer renewal and actual service dates before sale.',0,1,1,10);
