INSERT INTO plans (carrier_id,name,price_cents,data_allowance,talk,texts,validity_days,description,popular,active,verify_pricing,sort_order) VALUES (23,'$19.88 plan',1988,'4GB','Unlimited','Unlimited',0,'Published plan amount; exact renewal term and fulfilment must be confirmed. Official support introduces $19.88/4GB and $34.88/20GB, and upgrades $24.88 to 8GB. It retires $29.88/$39.88 for new selection while allowing existing users to remain. Do not confuse the $19.88 add-a-line rate with the standalone 4GB plan. Verify network, renewal term and SKU.',0,1,1,10);
