INSERT INTO settings (`key`,`value`) VALUES ('faqs','[{"question": "How does a prepaid top-up work?", "answer": "Choose the carrier for your existing US prepaid number, select an eligible refill, and pay securely. Our team processes the recharge manually. A payment receipt confirms your payment; a separate completion email confirms the recharge."}, {"question": "Do I need to create an account?", "answer": "No. You can check out without creating an account. Keep your order ID and checkout email to track your order or contact support."}, {"question": "How long will my recharge take?", "answer": "Our team fulfills orders manually after payment is confirmed. Timing depends on carrier availability and eligibility checks. We do not promise instant completion. Check your order status online or contact support for an update."}, {"question": "Can I top up someone else’s phone?", "answer": "Yes, if you are authorized to recharge the number and use the payment method. Confirm the recipient’s current prepaid carrier and exact mobile number before paying."}, {"question": "What if I enter the wrong number or carrier?", "answer": "Contact us immediately with your order ID. We will check whether fulfillment can still be stopped. Once a refill is delivered, carriers generally cannot move or reverse it."}, {"question": "Which payment methods can I use?", "answer": "When online checkout is enabled, card payments are handled securely by Stripe. The site does not receive or store your full card number or CVV. All prices and payments are in USD."}, {"question": "Can I recharge a postpaid or international number?", "answer": "This store is intended for eligible US prepaid accounts. It does not support postpaid bill payments, international numbers, new-line activation, or number transfers. Some carriers and plans have additional restrictions."}, {"question": "How do I track my order?", "answer": "Open Track order and enter your order ID plus the email used at checkout. Payment and recharge statuses are shown separately so you can see whether the refill is still processing or completed."}, {"question": "Is this an automatic recurring payment?", "answer": "No. Each order is a one-time payment. MI Tech Wireless does not enroll you in a recurring subscription. Your existing carrier account may have its own AutoPay settings."}]');
